using CallingBell.Api.Data;using Microsoft.EntityFrameworkCore;var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddDbContext<CallingBellDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));builder.Services.AddCors(o=>o.AddPolicy("Frontend",p=>p.AllowAnyHeader().AllowAnyMethod().WithOrigins("http://localhost:5173")));var app=builder.Build();if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseHttpsRedirection();app.UseCors("Frontend");app.MapControllers();app.Run();